  "finding_class": "learner-critical-answer",
  "rationale": "The cue and Malaysian answer are correct: balu specifically means a woman whose husband has died. Indonesian janda is valid but not specific to widowhood; it also commonly covers a divorced woman. The card needs an explicit false-friend contrast, and the Indonesian sense should be labeled as broader than the cue.",
  "claim_reviews": [
    {
      "subject": "English cue and sense",
      "conclusion": "Correct. 'Woman whose husband has died' accurately defines widow and appropriately narrows the intended sense.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=10456&keyword=balu"
      ]
    },
    {
      "subject": "Indonesian answer: janda",
      "conclusion": "Lexically valid but semantically broader: Indonesian janda can refer to a woman divorced or widowed, so it is not an unambiguous equivalent of the narrowed cue.",
      "material_risk": true,
      "evidence_refs": [
        "https://kbbi.web.id/janda"
      ]
    },
    {
      "subject": "Malaysian answer: balu",
      "conclusion": "Correct and specific. Malaysian balu denotes a woman whose husband has died.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=10456&keyword=balu"
      ]
    },
    {
      "subject": "Final relation",
      "conclusion": "Different-common-word is appropriate for the intended widow sense, because Indonesian janda and Malaysian balu are the ordinary corresponding forms, subject to the Indonesian breadth noted above.",
      "material_risk": false,
      "evidence_refs": [
        "https://kbbi.web.id/janda",
        "https://prpm.dbp.gov.my/Cari1?d=10456&keyword=balu"
      ]
    },
    {
      "subject": "False-friend contrast",
      "conclusion": "Required but missing. Learners should be told that Indonesian janda includes both widow and divorcee, while Malaysian usage commonly contrasts janda (divorced woman) with balu (widow).",
      "material_risk": true,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=175768&keyword=balu"
      ]
    }
  ]
}
